	bidValue := bidBase
	if bidSettings.IntervalMs > 0 && state.BidCount > 0 {
		increase := s.mulGweiClamped(slot, uint64(state.BidCount), bidSettings.IncreaseGwei) //nolint:gosec // BidCount >= 0
