	// Update state regardless of success - we don't want to spam on failure
	s.mu.Lock()
	state.LastBidTime = now
	state.LastBidHash = payload.BlockHash
	state.BidCount++
	bidCount := state.BidCount
	s.mu.Unlock()

	event := &BidSubmissionEvent{
		Slot:      slot,
		BlockHash: payload.BlockHash,
		Value:     bidValue,
		BidCount:  bidCount,
		SignedBid: signedBid,
