	if prefsBypassed {
		event.Warning = "no proposer preferences for slot — bid sent anyway (ignore_missing_prefs)"
	}

	if high, ok := s.bidTracker.GetHighestCompetitorBid(slot, s.bidCreator.GetBuilderIndex()); ok {
		event.CompetitorHighGwei = &high
