	event.Success = true
	event.Status = BidStatusSubmitted

	if s.service != nil {
		s.service.FireBidSubmission(event)
	}

	// Increment stats (count each bid submission)
	if s.service != nil && s.service.builderSvc != nil {
		s.service.builderSvc.IncrementBidsSubmitted()
	}

