func weiToETHString(wei *big.Int) string {
	if wei == nil {
		return "0.000000000000000000"
	}

	eth := new(big.Float).Quo(new(big.Float).SetInt(wei), big.NewFloat(1e18))

	return eth.Text('f', 18)
